solution.LruCache.java:
import java.util.*;
import java.util.function.BiConsumer;

class LruCache<K, V> {
    private final class Node {
        K key;
        V value;
        Node prev, next;
        Node(K key, V value) { this.key = key; this.value = value; }
    }

    private final int capacity;
    private final Map<K, Node> map = new HashMap<>();
    private final Node head = new Node(null, null);     // sentinels: head.next is the most recent
    private final Node tail = new Node(null, null);     // tail.prev is the least recent
    private BiConsumer<K, V> evictListener = (k, v) -> { };
    private long hits, misses, evictions;

    LruCache(int capacity) {
        if (capacity < 1) throw new IllegalArgumentException("capacity must be at least 1");
        this.capacity = capacity;
        head.next = tail;
        tail.prev = head;
    }

    private void unlink(Node n) {
        n.prev.next = n.next;
        n.next.prev = n.prev;
    }

    private void addFront(Node n) {
        n.next = head.next;
        n.prev = head;
        head.next.prev = n;
        head.next = n;
    }

    V get(K key) {
        Node n = map.get(key);
        if (n == null) {
            misses++;
            return null;
        }
        hits++;
        unlink(n);
        addFront(n);
        return n.value;
    }

    void put(K key, V value) {
        Node n = map.get(key);
        if (n != null) {
            n.value = value;
            unlink(n);
            addFront(n);
            return;
        }
        if (map.size() == capacity) {
            Node lru = tail.prev;
            unlink(lru);
            map.remove(lru.key);
            evictions++;
            evictListener.accept(lru.key, lru.value);
        }
        n = new Node(key, value);
        map.put(key, n);
        addFront(n);
    }

    boolean remove(K key) {
        Node n = map.remove(key);
        if (n == null) return false;
        unlink(n);
        return true;
    }

    int size() { return map.size(); }

    List<K> keys() {
        List<K> out = new ArrayList<>();
        for (Node n = head.next; n != tail; n = n.next) out.add(n.key);
        return out;
    }

    void onEvict(BiConsumer<K, V> listener) { this.evictListener = Objects.requireNonNull(listener); }

    Stats stats() { return new Stats(hits, misses, evictions); }
}

solution.Stats.java:
record Stats(long hits, long misses, long evictions) {
    double hitRate() {
        long total = hits + misses;
        return total == 0 ? 0 : (double) hits / total;
    }
}

unitTests:
test("basic use and eviction order", () -> {
    LruCache<String, Integer> c = new LruCache<>(3);
    c.put("a", 1); c.put("b", 2); c.put("c", 3);
    checkEq(c.keys(), List.of("c", "b", "a"));
    checkEq(c.get("a"), 1);
    checkEq(c.keys(), List.of("a", "c", "b"));
    c.put("d", 4);
    checkEq(c.keys(), List.of("d", "a", "c"));
    checkEq(c.get("b"), null);
    checkEq(c.size(), 3);
});

test("replacing and removing", () -> {
    LruCache<String, Integer> c = new LruCache<>(2);
    c.put("x", 1); c.put("y", 2);
    c.put("x", 10);
    checkEq(c.keys(), List.of("x", "y"));
    checkEq(c.get("x"), 10);
    checkEq(c.remove("y"), true);
    checkEq(c.remove("y"), false);
    c.put("z", 3); c.put("w", 4);
    checkEq(c.keys(), List.of("w", "z"));
});

test("eviction listener and stats", () -> {
    LruCache<Integer, String> c = new LruCache<>(2);
    List<String> evicted = new ArrayList<>();
    c.onEvict((k, v) -> evicted.add(k + "=" + v));
    c.put(1, "one"); c.put(2, "two");
    c.get(1); c.get(3);
    c.put(3, "three");
    c.put(1, "uno");
    c.remove(1);
    c.put(4, "four"); c.put(5, "five");
    checkEq(evicted, List.of("2=two", "3=three"));
    Stats s = c.stats();
    checkEq(s, new Stats(1, 1, 2));
    checkNear(s.hitRate(), 0.5);
    checkNear(new Stats(0, 0, 0).hitRate(), 0);
    checkThrows(IllegalArgumentException.class, () -> new LruCache<String, String>(0));
});

test("constant time with many operations", () -> {
    LruCache<Integer, Integer> c = new LruCache<>(50_000);
    for (int i = 0; i < 300_000; i++) {
        c.put(i, i * 2);
        if (i % 3 == 0) c.get(i / 2);
    }
    checkEq(c.size(), 50_000);
    checkEq(c.get(299_999), 599_998);
    checkEq(c.get(0), null);
    checkEq(c.keys().get(0), 299_999);
});

